    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages)
    best = None
    best_key = None

    def search(chosen, constraints, edges):
        nonlocal best, best_key
        unresolved = [name for name in constraints if name not in chosen]
        if not unresolved:
            # Every installed package was reached from a root; reject cycles.
            state, done = set(), set()
            def visit(name):
                if name in state:
                    return False
                if name in done:
                    return True
                state.add(name)
                if any(not visit(other) for other in edges.get(name, ())):
                    return False
                state.remove(name)
                done.add(name)
                return True
            if not all(visit(name) for name in chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in order)
            key = tuple(-x for x in vector) if not maximize else vector
            if best_key is None or key < best_key:
                best, best_key = dict(chosen), key
            return

        name = unresolved[0]
        low = max(pair[0] for pair in constraints[name])
        high = min(pair[1] for pair in constraints[name])
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        rows.sort(key=lambda row: row["version"], reverse=maximize)
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = {n: list(v) for n, v in constraints.items()}
            next_edges = {n: list(v) for n, v in edges.items()}
            active = [d for d in row.get("deps", [])
                      if not d.get("feature") or d.get("feature") in features]
            next_edges[name] = [d["name"] for d in active]
            valid = True
            for dep in active:
                target = dep["name"]
                next_constraints.setdefault(target, []).append((dep["min"], dep["max"]))
                if target in next_chosen and not (dep["min"] <= next_chosen[target] <= dep["max"]):
                    valid = False
                    break
            if valid:
                search(next_chosen, next_constraints, next_edges)

    initial = {name: [(bounds[0], bounds[1])]
               for name, bounds in data["roots"].items()}
    search({}, initial, {})
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


